@Component("condition-handler")
@ProcessingGroup("condition-processing-group")
public class ConditionEventHandler {
	
	// core constructor
	ConditionEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateConditionEvent
     */
    @EventHandler
    public void handle( CreateConditionEvent event) {
        entityManager.persist(new Condition(event.getConditionId(), event.getCode(), event.getOnsetDate(), event.getAbatementDate(), event.getPatient(), event.getClinicalStatus(), event.getVerificationStatus()));
    }

    /*
     * @param	event UpdateConditionEvent
     */
    @EventHandler
    public Condition handle( UpdateConditionEvent event) {
    	entityManager.merge(new Condition(event.getConditionId(), event.getCode(), event.getOnsetDate(), event.getAbatementDate(), event.getPatient(), event.getClinicalStatus(), event.getVerificationStatus()));
    }
    
    /*
     * @param	event DeleteConditionEvent
     */
    @EventHandler
    public void on( DeleteConditionEvent event) {
    	Condition entity = new Condition();
   
    	// ------------------------------------------
    	// apply the ConditionId
    	// ------------------------------------------
    	entity.setConditionId( event.getConditionId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ConditionRepository conditionEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ConditionEventHandler.class.getName());

}
